update lessons set objective_ar='أفهم الحديث الشريف «المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهى الله عنه»، وأحدّد توجيهاته، وأحلّل أسلوبه (القصر والكناية والتوازي)، وأربطه بكفّ الأذى في حياتنا.' where code='AR-Y8-N-T1-L12';
update success_criteria set statement_ar='أفسّر معاني الحديث وتوجيهاته.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T1-L12');
update success_criteria set statement_ar='أحلّل أسلوب القصر والكناية والتوازي في الحديث.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T1-L12');
update success_criteria set statement_ar='أربط الحديث بسلامة الناس من أذى القول والفعل اليوم، وأقترح مبادرة مدرسية.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T1-L12');
update lesson_summaries set content=content||'{"emoji": "🤝", "hook": "متى يكون الإنسان مسلمًا حقًّا؟ زميل يؤذي الناس بكلامه ويقول: أنا أصلّي وأصوم!", "idea": "حديث نبوي شريف يعرّف المسلم الحقّ بأنه من سلم الناس من أذى لسانه ويده، والمهاجر بأنه من ترك ما نهى الله عنه.", "learn": [["📖", "أقرأ الحديث في كتابي ص 110."], ["🎯", "«المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهى الله عنه»."], ["🧩", "تعريف الطرفين يفيد القصر، و«اللسان واليد» كناية عن القول والفعل."], ["🔎", "كفّ الأذى اليوم: لا تنمّر، ولا إساءة في التعليقات."], ["💡", "الهجرة الحقيقية: ترك المعاصي."]], "quiz": [["المسلم الحقّ من لا يؤذي الناس بقوله ولا فعله.", true], ["المهاجر في الحديث هو المسافر فقط.", false]], "words": [["سَلِمَ", "أمِن على نفسه وماله"], ["نَهى", "حرّم"], ["هَجَرَ", "ترك وأعرض عنه"], ["الْمُهاجِرُ", "التارك لما نهى الله عنه"]], "think": "كيف أطبّق «سلامة اللسان» في تعليقاتي على وسائل التواصل؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T1-L12');